<script setup lang="ts">
import { computed,nextTick,onMounted,ref } from 'vue'
import { useRoute } from 'vue-router'
import { api,errorText,hasRole } from '../api'
import { time,shortId } from '../composables'
import type { Runbook,RunbookVersion } from '../types'
import PageState from '../components/PageState.vue'
const route=useRoute(),id=String(route.params.id),book=ref<Runbook|null>(null),version=ref<RunbookVersion|null>(null),selected=ref<number>(Number(route.query.version)||0),title=ref(''),markdown=ref(''),reason=ref(''),busy=ref(false),loading=ref(false),error=ref(''),saveError=ref(''),notice=ref('')
const dirty=computed(()=>book.value&&(title.value!==book.value.title||markdown.value!==book.value.markdown))
async function load(){loading.value=true;error.value='';saveError.value='';try{book.value=await api<Runbook>('/runbooks/'+id);title.value=book.value.title;markdown.value=book.value.markdown;if(!selected.value)selected.value=book.value.latestVersion;await loadVersion()}catch(e){error.value=errorText(e)}finally{loading.value=false}}
async function loadVersion(){if(!selected.value){version.value=null;return}try{version.value=await api<RunbookVersion>(`/runbooks/${id}/versions/${selected.value}`);await nextTick();if(typeof route.query.section==='string')document.getElementById(route.query.section)?.scrollIntoView({block:'center'})}catch(e){error.value=errorText(e);version.value=null}}
async function change(action:'draft'|'publish'|'state'){if(!book.value)return;busy.value=true;saveError.value='';notice.value='';try{const payload=action==='draft'?{revision:book.value.revision,title:title.value,markdown:markdown.value,reason:reason.value}:action==='state'?{revision:book.value.revision,enabled:!book.value.enabled,reason:reason.value}:{revision:book.value.revision,reason:reason.value};book.value=await api<Runbook>(`/runbooks/${id}/${action}`,{method:action==='publish'?'POST':'PUT',body:payload});title.value=book.value.title;markdown.value=book.value.markdown;selected.value=book.value.latestVersion;await loadVersion();notice.value=action==='publish'?'已发布新版本，历史版本保持只读。':action==='draft'?'草稿已保存。':'状态已更新。';reason.value=''}catch(e){saveError.value=errorText(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><RouterLink :to="{path:'/runbooks',query:{targetId:book?.targetId}}" class="back-link">← 运行手册</RouterLink><PageState :loading="loading&&!book" :error="error" @retry="load"><template v-if="book"><div class="page-heading"><div><h1>{{ book.title }}</h1><p>{{ book.enabled?'已启用':'已停用，新诊断不再检索此手册' }} · 当前草稿修订 {{ book.revision }}</p></div><button class="btn" :disabled="busy" @click="load">{{ dirty?'刷新最新（覆盖未保存内容）':'刷新最新' }}</button></div><div v-if="saveError" class="error-message" role="alert">{{ saveError }} <button class="text-button" @click="load">刷新最新（覆盖未保存内容）</button></div><p v-if="notice" class="notice" role="status">{{ notice }}</p><section v-if="hasRole('OPS_ADMIN')" class="panel runbook-editor"><h2>编辑草稿</h2><p class="muted">保存与发布分开进行。发布后的段落与引用保持不变。</p><label>标题<input v-model="title" required maxlength="160" :disabled="busy" /></label><label>Markdown 正文<textarea v-model="markdown" maxlength="24000" rows="12" :disabled="busy"></textarea></label><p class="form-hint">最多 5 个标题段落，每段 6,000 字。手册内容作为参考资料，不会被平台执行。</p><label>本次操作理由<input v-model="reason" maxlength="500" :disabled="busy" /></label><div class="form-actions"><button class="btn" :disabled="busy||!dirty||!title.trim()||!markdown.trim()||!reason.trim()" @click="change('draft')">保存草稿</button><button class="btn primary" :disabled="busy||!!dirty||!book.hasUnpublishedChanges||!book.enabled||!reason.trim()" @click="change('publish')">发布新版本</button><button class="btn" :disabled="busy||!!dirty||!reason.trim()" @click="change('state')">{{ book.enabled?'停用手册':'重新启用' }}</button></div></section><section class="panel published-book"><div class="panel-heading"><div><h2>已发布版本 · 只读</h2><p class="muted">历史引用在停用或更新后仍可查看。</p></div><label v-if="book.latestVersion">版本<select v-model="selected" @change="loadVersion"><option v-for="v in book.latestVersion" :key="v" :value="v">v{{ v }}</option></select></label></div><PageState :empty="!version" title="尚未发布" description="草稿发布后，才会纳入诊断输入。"><template v-if="version"><p class="muted version-meta">{{ version.title }} · {{ time(version.publishedAt) }}</p><article v-for="section in version.sections" :id="section.id" :key="section.id" class="runbook-section" :class="{cited:route.query.section===section.id}"><pre>{{ section.text }}</pre><div class="section-meta"><code :title="section.id">段落 {{ shortId(section.id) }}</code><code :title="section.hash">SHA-256 {{ section.hash.slice(0,12) }}…</code></div></article></template></PageState></section></template></PageState></template>
<style scoped>.runbook-editor{padding:24px;margin-bottom:24px}.runbook-editor h2{margin-bottom:8px}.runbook-editor>label{margin-top:18px}.published-book{margin-bottom:24px}.version-meta{padding:0 24px}.runbook-section{padding:24px;border-top:1px solid var(--border)}.runbook-section.cited{border-left:4px solid var(--accent);background:#f0f7f1}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;line-height:1.8;margin:0}.section-meta{display:flex;flex-wrap:wrap;gap:16px;font-size:11px;color:var(--muted);margin-top:16px}</style>
